/* ui/settings.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function mountSettings() {
    document.querySelectorAll("[data-player-settings-mount]").forEach((mount) => {
      if (!mount.querySelector("[data-player-setting]")) mount.innerHTML = P.settingsFormHtml();
    });
    P.syncProgramLockUi();
    P.syncSettingsUI();
  }

  function syncSettingsUI() {
    document.querySelectorAll("[data-player-setting]").forEach((input) => {
      const key = input.dataset.playerSetting;
      if (key === "engine" || key === "format" || key === "playbackMode" || key === "pitchMode"
        || key === "limiterMode" || key === "remixFormat") {
        if (input instanceof HTMLSelectElement) input.value = String(P.state[key]);
        else input.checked = String(input.value) === String(P.state[key]);
      }
      else if (key === "fxBakeDelayMs") input.value = String(P.bakeDelayMs());
      else if (key === "playbackRate") input.value = String(P.clampPlaybackRate(P.state.playbackRate));
      else if (key === "fadeOutMs") input.value = String(P.state.fadeOutMs);
      else if (key === "fadeInMs") input.value = String(P.state.fadeInMs);
      else if (key === "silenceDb") input.value = String(P.state.silenceDb);
      else if (key === "introMaxSec") input.value = String(P.state.introMaxSec);
      else if (P.FX_RANGES[key]) input.value = String(P.state[key]);
      else if (key === "autoNext" || key === "rememberPosition" || key === "crossfade" || key === "fadeInEnabled" || key === "fadeOutEnabled"
        || key === "skipIntro" || key === "eqEnabled" || key === "limiterEnabled"
        || P.FX_KINDS.some((kind) => key === `${kind}Enabled`)) {
        input.checked = !!P.state[key];
      }
    });
    P.syncFadeVisual();
    P.syncIntroVisual();
    P.syncPlaybackVisual();
    P.syncEqVisual();
    P.syncFxVisual();
  }

  function openSettings() {
    if (P.settingsTimer) { window.clearTimeout(P.settingsTimer); P.settingsTimer = 0; }
    if (P.queuePanel && !P.queuePanel.hidden) P.closeQueue();
    P.settingsPanel.hidden = false;
    document.body.classList.add("player-settings-open");
    P.settingsToggle.setAttribute("aria-expanded", "true");
    P.mountSettings();
    // Restart the transition even if the panel was still closing.
    void P.settingsPanel.offsetWidth;
    P.settingsPanel.classList.add("is-open");
    P.startLimiterMeter();
    const first = P.settingsPanel.querySelector("select, input");
    if (first) first.focus({ preventScroll: true });
  }

  function closeSettings() {
    if (P.settingsPanel.hidden) return;
    P.settingsToggle.setAttribute("aria-expanded", "false");
    P.settingsPanel.classList.remove("is-open");
    if (P.settingsTimer) window.clearTimeout(P.settingsTimer);
    P.stopLimiterMeter();
    // Keep the panel in the DOM until its fade/slide-out has finished.
    P.settingsTimer = window.setTimeout(() => {
      if (!P.settingsPanel.classList.contains("is-open")) {
        P.settingsPanel.hidden = true;
        document.body.classList.remove("player-settings-open");
      }
      P.settingsTimer = 0;
    }, 260);
  }
  Object.assign(P, { mountSettings, syncSettingsUI, openSettings, closeSettings });
}
